#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>

struct ImpactProject {
    std::string name;
    std::string domain;
    double budgetNeeded;
    double expectedBeneficiaries;

    double impactScore() const {
        return (budgetNeeded > 0.0) ? (expectedBeneficiaries / budgetNeeded) : 0.0;
    }
};

int main() {
    std::vector<ImpactProject> initiatives = {
        {"Emergency Net Connectivity", "Disaster Relief (NetHope)", 50000.0, 120000.0},
        {"Solar Irrigation Grid", "Clean Energy (UNIDO)", 80000.0, 95000.0},
        {"Vaccine Cold Chain Tracking", "Global Health (Gates Foundation)", 60000.0, 180000.0},
        {"Rainforest Canopy Acoustic Sensor", "Conservation (Rainforest Fdn)", 30000.0, 45000.0}
    };

    // Sort in descending order of beneficiaries per dollar
    std::sort(initiatives.begin(), initiatives.end(), [](const ImpactProject& a, const ImpactProject& b) {
        return a.impactScore() > b.impactScore();
    });

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Humanitarian & Environmental Project Priority:\n";
    std::cout << "-------------------------------------------------\n";

    double availableGrant = 120000.0;
    double remainingBudget = availableGrant;

    for (const auto& [name, domain, cost, people] : initiatives) {
        std::cout << "Initiative : " << name << "\n";
        std::cout << "Domain     : " << domain << "\n";
        std::cout << "Cost       : $" << cost << " | Beneficiaries: " << people << "\n";
        std::cout << "Ratio      : " << (people / cost) << " people/$\n";

        if (cost <= remainingBudget) {
            remainingBudget -= cost;
            std::cout << "Status     : FUNDED FULLY\n";
        } else if (remainingBudget > 0.0) {
            std::cout << "Status     : PARTIALLY FUNDED ($" << remainingBudget << ")\n";
            remainingBudget = 0.0;
        } else {
            std::cout << "Status     : DEFERRED (Wait for Next Grant)\n";
        }
        std::cout << "-------------------------------------------------\n";
    }

    std::cout << "Remaining Balance: $" << remainingBudget << "\n";
    return 0;
}
